import sys
sys.path.insert(0, "/home/claude/winesite/scripts/c8")
from common import site

I = "hu"
SITES = [
site(I, "eger-castle", "Eger Castle", "historic", 47.9041, 20.3795, "In 1552 István Dobó's garrison of about 2,000 held Eger castle for 39 days against a far larger Ottoman army. Later legend says red wine stained the defenders' beards and the Turks thought they drank bull's blood, the story behind Egri Bikavér. Eger fell in 1596 and stayed Ottoman until 1687.", "precise", "Historic site", "Eger"),
site(I, "szepasszony-volgy", "Szépasszony-völgy", "cellar", 47.8902, 20.3589, "The 'Valley of the Beautiful Woman' on the south-west edge of Eger is lined with around 200 cellars cut into soft rhyolite tuff, many now tasting rooms. It is the classic place to taste Egri Bikavér from the barrel, and the name's origin (a pagan goddess, a beautiful innkeeper) is still argued over.", "precise", "Historic cellar row", "Eger"),
site(I, "nagy-eged", "Nagy-Eged", "vineyard", 47.9245, 20.4163, "Nagy-Eged is the steep limestone and tuff hill north-east of Eger, rising to about 535 m, with south-facing terraces. It is considered the town's finest red-wine site, especially for Kékfrankos and Pinot Noir, and features in many Grand Superior Bikavérs.", "approx", "Single vineyard", "Eger", ["St. Andrea", "Gál Tibor", "Bolyki"]),
site(I, "villany-cellar-row", "Villány cellar row and Wine Museum", "cellar", 45.8682, 18.4529, "Villány's Baross Gábor and Batthyány streets are lined with the cellars and press houses of the German-descended families who rebuilt the area after the Ottoman wars. The Wine Museum occupies an 18th-century cellar in the middle of the row.", "precise", "Cellar row and museum", "Villány", ["Bock", "Gere Attila"]),
site(I, "palkonya-cellar-village", "Palkonya cellar village", "cellar", 45.8929, 18.3944, "Palkonya's whitewashed press houses, about 50 of them, run in a row along a single lane below the vines. The village, settled by Swabians, is one of the best-preserved small cellar villages in the Villány district.", "precise", "Cellar village", "Villány"),
site(I, "villany-kopar", "Kopár", "vineyard", 45.8508, 18.4189, "Kopár ('bare') is a steep, stony south-facing limestone slope at Nagyharsány. Its name describes how thin the topsoil is. Gere Attila's flagship red, a Cabernet Franc-led blend, is named after it, and it remains Villány's best-known single vineyard.", "approx", "Single vineyard", "Villány", ["Gere Attila"]),
site(I, "villany-jammertal", "Jammertal", "vineyard", 45.8716, 18.4390, "Jammertal ('valley of lamentation') is a historic Villány vineyard. Its name is said to recall a battle near here in the 1687 campaign. It is now planted with Cabernet Franc and other reds and is home to the Jammertal hotel and winery.", "approx", "Single vineyard", "Villány"),
site(I, "szekszard-heimann", "Heimann & Fiai", "estate", 46.3376, 18.6875, "The Heimann family estate in the Iván valley near Szekszárd has led the revival of Kadarka, collecting and replanting old local clones. It also makes some of the district's finest Bikavér and Cabernet Franc.", "precise", "Family estate", "Szekszárd", ["Heimann & Fiai"]),
site(I, "somlo-hill", "Somló hill", "landscape", 47.1465, 17.3719, "A lone extinct volcano rising to 432 m out of the flat Kisalföld, Somló is topped by a castle ruin and wrapped in small vineyards and press houses. Its basalt soils give Hungary's most mineral whites, the Juhfark-led 'wedding night wine' said to guarantee a son.", "precise", "Volcanic butte", "Somlói"),
site(I, "badacsony-hill", "Badacsony hill", "landscape", 46.8033, 17.4962, "Badacsony is a coffin-shaped basalt butte on the north shore of Lake Balaton. Its columnar basalt 'organ pipes' tower over terraces of Olaszrizling, Szürkebarát and Kéknyelű, and poet Sándor Kisfaludy's press house still stands on its slope.", "precise", "Volcanic butte", "Badacsony"),
site(I, "szent-gyorgy-hegy", "Szent György-hegy", "landscape", 46.8415, 17.4484, "Szent György-hegy (415 m) near Tapolca is a basalt witness hill whose columnar 'organ pipes' and old press houses make it one of the most beautiful vineyard hills in Hungary. Its wines are part of the Badacsony PDO.", "precise", "Volcanic butte", "Badacsony"),
site(I, "tihany-abbey", "Tihany Benedictine Abbey", "historic", 46.9137, 17.8897, "Founded in 1055 by King Andrew I, the abbey on the Tihany peninsula owned vineyards from its first charter. That charter is famous for containing the oldest surviving written Hungarian words. The peninsula is now a red-wine PDO.", "precise", "Historic monastery", "Tihany"),
site(I, "pannonhalma-abbey", "Pannonhalma Archabbey Winery", "historic", 47.5499, 17.7650, "The Benedictine archabbey founded in 996, a UNESCO World Heritage Site since 1996, has grown wine for a millennium. Its modern winery, rebuilt in 2003 on the old vineyard terraces, makes Rajnai rizling, Sauvignon Blanc, Tramini and Pinot Noir.", "precise", "Monastic winery", "Pannonhalma", ["Pannonhalmi Apátsági Pincészet"]),
site(I, "torley-budafok", "Törley, Budafok", "house", 47.4309, 19.0354, "József Törley learned sparkling winemaking in Reims and in 1882 moved his business to Budafok on the southern edge of Budapest, attracted by its limestone cellars and nearby vineyards. Törley remains Hungary's biggest sparkling wine house; the family's mansion is nearby.", "precise", "Sparkling wine house", "Etyek-Buda", ["Törley"]),
site(I, "hajos-pincefalu", "Hajós cellar village", "cellar", 46.3851, 19.1497, "Outside the village of Hajós lies a separate 'village' of more than 1,200 cellars and press houses in neat streets, built by Swabian settlers from the 18th century. It is one of the largest cellar villages in Central Europe and hosts a festival every May.", "precise", "Cellar village", "Hajós-Baja"),
site(I, "fertorakos", "Fertőrákos quarry", "historic", 47.7263, 16.6433, "This Leitha limestone quarry beside Lake Fertő has been worked since Roman times. Stone from here helped build Vienna, and its huge cavern halls are part of the Fertő/Neusiedlersee UNESCO landscape. The same limestone underlies some of Sopron's Kékfrankos vineyards.", "precise", "Historic quarry (UNESCO landscape)", "Sopron"),
site(I, "miklostelep", "Kecskemét and the sand vineyards", "historic", 46.9075, 19.6922, "Kecskemét is the hub of the Kunság. In 1883 the town gave the state land for the Miklóstelep demonstration vineyard, which proved that vines on loose sand escape phylloxera. Commissioner Gyula Miklós's experiment made the Great Plain Hungary's largest vineyard.", "approx", "Historic site", "Kunság"),
site(I, "debro-feldebro", "Aldebrő and Feldebrő", "village", 47.7892, 20.2284, "The twin villages of Aldebrő and Feldebrő at the eastern foot of the Mátra are the heart of the Debrői Hárslevelű PDO. Feldebrő's church has a crypt with 11th-century frescoes, among the oldest in Hungary.", "approx", "Village", "Debrői Hárslevelű"),
site(I, "csopak-village", "Csopak", "village", 46.9797, 17.9231, "Csopak lies on the north-east shore of Lake Balaton among slopes of red Permian sandstone and slate. Its growers' 2012 'Csopak Codex' and the 2020 Csopak PDO made Olaszrizling a serious terroir wine.", "precise", "Village", "Csopak", ["Jásdi", "Szent Donát"]),
site(I, "koszeg", "Kőszeg", "village", 47.3895, 16.5407, "Kőszeg is a walled town on the Austrian border with its own PDO since 2025. Every year since 1740 the town has drawn the length of the young vine shoots on St George's Day into its 'Book of the Coming of the Grapes', a rare record of budbreak.", "approx", "Town", "Kőszeg"),
]
